from pathlib import Path
import json,cv2,numpy as np
r=Path(__file__).resolve().parent;results={}
for folder in ['20261101_145243_cam1','20261101_145225_cam2']:
 p=r/folder;m=json.loads((p/'metadata.json').read_text());v=np.load(p/'top_size_points.npz');q=np.column_stack([(v['points']-v['origin'])@v['e1'],(v['points']-v['origin'])@v['e2']]).astype(np.float32);rect=cv2.minAreaRect(q);dims=np.sort(rect[1])*1000;err=dims-50
 camera=m['camera'];result={'source_capture':str(p),'method':'Minimum-area rectangle of observed valid depth points near fitted visible top plane; no nominal size constraint, no depth-hole filling','visible_depth_extent_mm':dims.tolist(),'nominal_size_mm':[50,50],'extent_difference_from_nominal_mm':err.tolist(),'full_boundary_verified':False,'interpretation':'Visible top depth extent agrees within 2.5mm, but missing edge data can underestimate full width' if camera=='cam1' else 'Extent inconsistent with nominal object; partial grazing-view depth and edge artefacts prevent reliable size validation','size_validation_status':'partial agreement, full edges unverified' if camera=='cam1' else 'not validated','top_plane_fit_data':str(p/'top_size_points.npz')}
 results[camera]=result
 im=cv2.imread(str(p/'color.png'));corners=cv2.boxPoints(rect);xyz=v['origin']+corners[:,0,None]*v['e1']+corners[:,1,None]*v['e2'];K=np.array(m['K']).reshape(3,3);D=np.array(m['D']);pix=cv2.projectPoints(xyz,np.zeros(3),np.zeros(3),K,D)[0].reshape(-1,2).round().astype(np.int32);cv2.polylines(im,[pix],True,(0,255,0) if camera=='cam1' else (0,165,255),2);cv2.putText(im,f'{camera}: visible depth {dims[0]:.1f} x {dims[1]:.1f} mm',(12,28),cv2.FONT_HERSHEY_SIMPLEX,.55,(0,255,255),2);cv2.imwrite(str(p/'size_review.png'),im)
 (p/'size_validation.json').write_text(json.dumps(result,ensure_ascii=False,indent=2))
(r/'orange_box_xy_size_validation.json').write_text(json.dumps({'nominal_box_mm':[50,50,60],'results':results,'limitations':['Results are from stored captures at the turntable position','Only visible valid depth points used; full boundary and absolute scale across workspace not independently verified','No camera or motor settings changed']},ensure_ascii=False,indent=2));print(json.dumps(results,ensure_ascii=False,indent=2))
